Here is the commit message:
drm/amdgpu: fix drm panic null pointer when driver not
 support atomic

When driver not support atomic, fb using plane->fb rather than
plane->state->fb.

Fixes: fe151ed7af54 ("drm/amdgpu: add generic display panic helper code")
Signed-off-by: Lu Yao <yaolu@kylinos.cn>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>
(cherry picked from commit 2f2a72de673513247cd6fae14e53f6c40c5841ef)

Here is the root cause:
The code unconditionally uses plane->state->fb, but when the driver does not support atomic modesetting, plane->state is NULL, causing a null pointer dereference. The fix correctly uses plane->fb for non-atomic drivers.

Here is the patch:

 int amdgpu_display_get_scanout_buffer(struct drm_plane *plane,
 				      struct drm_scanout_buffer *sb)
 {
 	struct amdgpu_bo *abo;
-	struct drm_framebuffer *fb = plane->state->fb;
+	struct drm_framebuffer *fb;
+
+	if (drm_drv_uses_atomic_modeset(plane->dev))
+		fb = plane->state->fb;
+	else
+		fb = plane->fb;

 	if (!fb)
 		return -EINVAL;

 	DRM_DEBUG_KMS("Framebuffer %dx%d %p4cc\n", fb->width, fb->height, &fb->format->format);

 	abo = gem_to_amdgpu_bo(fb->obj[0]);
 	if (!abo)
 		return -EINVAL;

 	sb->width = fb->width;
 	sb->height = fb->height;
 	/* Use the generic linear format, because tiling will be disabled in panic_flush() */
 	sb->format = drm_format_info(fb->format->format);
 	if (!sb->format)
 		return -EINVAL;

 	sb->pitch[0] = fb->pitches[0];

 	if (abo->flags & AMDGPU_GEM_CREATE_NO_CPU_ACCESS) {
 		if (abo->tbo.resource->mem_type != TTM_PL_VRAM) {
 			drm_warn(plane->dev, "amdgpu panic, framebuffer not in VRAM\n");
 			return -EINVAL;
 		}
 		/* Only handle 32bits format, to simplify mmio access */
 		if (fb->format->cpp[0] != 4) {
 			drm_warn(plane->dev, "amdgpu panic, pixel format is not 32bits\n");
 			return -EINVAL;
 		}
 		sb->set_pixel = amdgpu_display_set_pixel;
 		panic_abo = abo;
 		return 0;
 	}
 	if (!abo->kmap.virtual &&
 	    ttm_bo_kmap(&abo->tbo, 0, PFN_UP(abo->tbo.base.size), &abo->kmap)) {
 		drm_warn(plane->dev, "amdgpu bo map failed, panic won't be displayed\n");
 		return -ENOMEM;
 	}
 	if (abo->kmap.bo_kmap_type & TTM_BO_MAP_IOMEM_MASK)
 		iosys_map_set_vaddr_iomem(&sb->map[0], abo->kmap.virtual);
 	else
 		iosys_map_set_vaddr(&sb->map[0], abo->kmap.virtual);

 	return 0;
 }
-- 


